#[derive(Clone, Copy, Debug, PartialEq)]
#[repr(u16)]
pub enum Model142ReadOnly {
    Readwrite = 0,
    Readonly = 1,
}

impl Model142ReadOnly {
    pub fn from_repr(repr: u16) -> Option<Model142ReadOnly> {
        match repr {
            0 => Some(Model142ReadOnly::Readwrite),
            1 => Some(Model142ReadOnly::Readonly),
            _ => None,
        }
    }
}

/// Short, spec-matching alias for [`Model142ReadOnly`] - only `Model142ReadOnly` (unique per model) reaches the generated C header, since cbindgen has no module system to keep `ReadOnly` distinct from another model's point of the same name.
pub type ReadOnly = Model142ReadOnly;
